begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('81000000-0000-4000-8000-000000000001'),('81000000-0000-4000-8000-000000000002'),('81000000-0000-4000-8000-000000000003');
insert into deardaily_private.owners(user_id) values('81000000-0000-4000-8000-000000000001');
insert into deardaily_private.moderators(user_id) values('81000000-0000-4000-8000-000000000003');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in ('deardaily_private.owners'::regclass,'deardaily_private.publishing_bans'::regclass,'deardaily_private.owner_audit'::regclass,'deardaily_private.owner_notices'::regclass)),'all owner tables force RLS');
set local role anon;
select throws_ok($$select public.my_owner_access()$$,'42501',null,'anonymous cannot inspect owner role');
select throws_ok($$select public.owner_public_stories()$$,'42501',null,'anonymous cannot list owner queue');
select throws_ok($$select public.my_moderation_notices()$$,'42501',null,'anonymous cannot read notices');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2","user_metadata":{"admin":true}}',true);
select is(public.my_owner_access()->>'owner','false','editable metadata never grants owner');
select throws_ok($$insert into deardaily_private.owners(user_id) values(auth.uid())$$,'42501',null,'client cannot self-assign owner');
select throws_ok($$select public.owner_public_stories()$$,'42501',null,'ordinary aal2 cannot list owner queue');
select throws_ok($$select public.owner_publishing_bans()$$,'42501',null,'ordinary aal2 cannot list bans');
select throws_ok($$select public.owner_moderate_story(gen_random_uuid(),true,'spoof')$$,'42501',null,'ordinary aal2 cannot ban');
select throws_ok($$select public.owner_restore_publishing(auth.uid(),'spoof')$$,'42501',null,'ordinary aal2 cannot restore publishing');
select lives_ok($$insert into public.journal_entries(id,title,body) values('82000000-0000-4000-8000-000000000001','Private B one','SECRET B'),('82000000-0000-4000-8000-000000000002','Private B two','SECRET B TWO'),('82000000-0000-4000-8000-000000000003','Private B three','SECRET B THREE')$$,'B private source fixtures');
select lives_ok($$insert into public.public_stories(id,user_id,title,body) values('82000000-0000-4000-8000-000000000001',auth.uid(),'Anonymous public one','Approved public words'),('82000000-0000-4000-8000-000000000002',auth.uid(),'Anonymous public two','Approved public words')$$,'B explicitly publishes anonymous snapshots');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.owner_public_stories()$$,'42501',null,'ordinary moderator cannot use owner controls');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is(public.my_owner_access()->>'owner','true','backend recognizes assigned owner');
select is(public.my_owner_access()->>'mfa','false','low assurance is disclosed');
select throws_ok($$select public.owner_public_stories()$$,'42501',null,'owner aal1 cannot list');
select throws_ok($$select public.owner_publishing_bans()$$,'42501',null,'owner aal1 cannot list bans');
select throws_ok($$select public.owner_moderate_story('82000000-0000-4000-8000-000000000001',false,'reason')$$,'42501',null,'owner aal1 cannot remove');
select throws_ok($$select public.owner_restore_publishing('81000000-0000-4000-8000-000000000002','reason')$$,'42501',null,'owner aal1 cannot restore');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select is(public.my_owner_access()->>'mfa','true','verified owner MFA session recognized');
select is(jsonb_array_length(public.owner_public_stories()),2,'owner sees public snapshots including anonymous ones');
select ok(not(public.owner_public_stories()->0 ? 'user_id') and not(public.owner_public_stories()->0 ? 'body'),'owner list minimizes fields');
select is((select count(*) from public.journal_entries),0::bigint,'owner MFA still cannot read B private journals');
select throws_ok($$select public.owner_public_stories(-1)$$,'22023',null,'invalid pages denied');
select throws_ok($$select public.owner_moderate_story('82000000-0000-4000-8000-000000000001',false,' ')$$,'22023',null,'reason required');
select lives_ok($$select public.owner_moderate_story('82000000-0000-4000-8000-000000000001',false,'Synthetic removal reason')$$,'owner removes unreported anonymous story');
select is(jsonb_array_length(public.owner_public_stories()),1,'only selected story removed');
select lives_ok($$select public.owner_moderate_story('82000000-0000-4000-8000-000000000002',true,'Synthetic publishing restriction')$$,'owner bans anonymous author by immutable backend owner');
select is(jsonb_array_length(public.owner_public_stories()),0,'ban removes all remaining public stories');
select is(jsonb_array_length(public.owner_publishing_bans()),1,'owner can review active ban');
select is(jsonb_array_length(public.my_moderation_notices()),0,'owner cannot read recipient notices');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select is((select count(*) from public.journal_entries),3::bigint,'ban preserves all private journals');
select lives_ok($$update public.journal_entries set body='STILL PRIVATE' where id='82000000-0000-4000-8000-000000000003'$$,'banned author can keep writing privately');
select throws_ok($$insert into public.public_stories(id,user_id,title,body) values('82000000-0000-4000-8000-000000000003',auth.uid(),'Attempt','Denied')$$,'42501',null,'direct API publish denied while banned');
select is(jsonb_array_length(public.my_moderation_notices()),2,'affected author receives removal and ban reasons');
select ok(exists(select 1 from jsonb_array_elements(public.my_moderation_notices()) n where n->>'reason'='Synthetic publishing restriction'),'notice contains specific reason');
select ok(not(public.my_moderation_notices()->0 ? 'actor_id') and not(public.my_moderation_notices()->0 ? 'user_id'),'notice hides actor and ownership IDs');
select throws_ok($$select * from deardaily_private.owner_audit$$,'42501',null,'audit cannot be read through client tables');
select throws_ok($$delete from deardaily_private.publishing_bans$$,'42501',null,'banned author cannot remove ban');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.owner_restore_publishing('81000000-0000-4000-8000-000000000002','Synthetic restoration')$$,'owner restores future publishing');
select is(jsonb_array_length(public.owner_publishing_bans()),0,'ban removed');
select lives_ok($$insert into public.journal_entries(id,title,body) values('82000000-0000-4000-8000-000000000004','Owner source','Owner private')$$,'owner source fixture');
select lives_ok($$insert into public.public_stories(id,user_id,title,body) values('82000000-0000-4000-8000-000000000004',auth.uid(),'Owner public','Owner public')$$,'owner publication');
select throws_ok($$select public.owner_moderate_story('82000000-0000-4000-8000-000000000004',true,'self')$$,'22023',null,'owner cannot accidentally ban own account');
select set_config('request.jwt.claims','{"sub":"81000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$insert into public.public_stories(id,user_id,title,body) values('82000000-0000-4000-8000-000000000003',auth.uid(),'New public story','Approved')$$,'unbanned author can publish new entry');
select throws_ok($$insert into public.public_stories(id,user_id,title,body) values('82000000-0000-4000-8000-000000000001',auth.uid(),'Old removed story','Denied')$$,'42501',null,'removed entry stays blocked after unban');
select is(jsonb_array_length(public.my_moderation_notices()),3,'restoration reason also delivered privately');
select is((select count(*) from public.journal_entries),3::bigint,'B cannot read owner source after unban');
reset role;
select is((select count(*) from deardaily_private.owner_audit),3::bigint,'all owner decisions audited');
select * from finish();
rollback;
